// Portada de arranque "Skyendo": sale unos 2,5 s al empezar el juego, en vez del logo de la consola.
// Fondo de cuadros azules (como el resto de la interfaz nueva) y el logo en el centro, con fundido de entrada y salida.
//
// El logo va metido aquí como imagen RGBA con paleta de 48 colores comprimida en parejas (índice, repeticiones),
// porque en iOS no hay carpeta del proyecto de la que leer archivos. Se generó con Pillow a partir de la fuente
