static SDL_Texture *tex_logo;
static int acabada;

// devuelve 1 mientras la portada se ve (y la ha pintado), 0 cuando ya ha terminado
int skyendo_pinta(SDL_Renderer *r, int ancho, int alto, uint32_t ms)
{
    if (acabada) return 0;
    if (ms >= T_FIN) {
        if (tex_logo) SDL_DestroyTexture(tex_logo);
        tex_logo = NULL;
        acabada = 1;
        return 0;
    }
    if (!tex_logo) {  // se crea la primera vez, en el hilo que pinta
        uint8_t *px = malloc(LOGO_ANCHO * LOGO_ALTO * 4), *p = px;
        if (!px) return 0;
        for (size_t i = 0; i < sizeof logo_rle; i += 2)
            for (int n = 0; n < logo_rle[i + 1]; n++, p += 4)
                SDL_memcpy(p, &logo_paleta[logo_rle[i] * 4], 4);
        tex_logo = SDL_CreateTexture(r, SDL_PIXELFORMAT_RGBA32, SDL_TEXTUREACCESS_STATIC, LOGO_ANCHO, LOGO_ALTO);
        if (tex_logo) {
            SDL_UpdateTexture(tex_logo, NULL, px, LOGO_ANCHO * 4);
            SDL_SetTextureBlendMode(tex_logo, SDL_BLENDMODE_BLEND);
            SDL_SetTextureScaleMode(tex_logo, SDL_ScaleModeLinear);
        }
        free(px);
    }

    float a = ms < T_ENTRA ? ms / (float)T_ENTRA : ms > T_SALE ? (T_FIN - ms) / (float)(T_FIN - T_SALE) : 1.0f;
    Uint8 a8 = (Uint8)(a * 255.0f + 0.5f);

    // guarda el estado de dibujo de quien llama para dejarlo como estaba
    Uint8 cr, cg, cb, ca;
    SDL_BlendMode modo;
    SDL_GetRenderDrawColor(r, &cr, &cg, &cb, &ca);
    SDL_GetRenderDrawBlendMode(r, &modo);
    SDL_SetRenderDrawBlendMode(r, SDL_BLENDMODE_BLEND);

    // fondo blanco liso, como la pantalla de arranque de la consola
    SDL_SetRenderDrawColor(r, 0xFF, 0xFF, 0xFF, a8);
    SDL_RenderFillRect(r, NULL);

    // logo centrado, cabe en el 72% del ancho y el 55% del alto sin deformarse
    if (tex_logo) {
        float e = SDL_min(ancho * 0.72f / LOGO_ANCHO, alto * 0.55f / LOGO_ALTO);
        SDL_FRect d = {(ancho - LOGO_ANCHO * e) / 2, (alto - LOGO_ALTO * e) / 2, LOGO_ANCHO * e, LOGO_ALTO * e};
        SDL_SetTextureAlphaMod(tex_logo, a8);
        SDL_RenderCopyF(r, tex_logo, NULL, &d);
    }

    SDL_SetRenderDrawColor(r, cr, cg, cb, ca);
    SDL_SetRenderDrawBlendMode(r, modo);
    return 1;
}
